import json
import pandas as pd
import numpy as np

DATA_FILE = "/home/chs/Work/tga_plot/eval/inputs_b/polymers.xlsx"

df = pd.read_excel(DATA_FILE, sheet_name="PE")
df.columns = [str(c).strip() for c in df.columns]

temp_col = next(c for c in df.columns if "Temperature" in c)
weight_col = next(c for c in df.columns if "Weight" in c and "Deriv" not in c)

temperature_c = pd.to_numeric(df[temp_col], errors="coerce")
weight = pd.to_numeric(df[weight_col], errors="coerce")
valid = temperature_c.notna() & weight.notna()

data = [
    [round(float(t + 273.15), 4), round(float(w), 6)]
    for t, w in zip(temperature_c[valid], weight[valid])
]

option = {
    "animation": False,
    "textStyle": {"fontFamily": "Noto Sans CJK KR"},
    "title": {
        "text": "PE TGA",
        "left": "center",
