        "trigger": "axis",
        "axisPointer": {"type": "cross"}
    },
    "grid": {"left": 78, "right": 30, "top": 70, "bottom": 65},
    "xAxis": {
        "type": "value",
        "name": "온도 (K)",
        "nameLocation": "middle",
        "nameGap": 38,
        "min": 303.15,
        "max": 1173.15,
        "axisLabel": {"formatter": "{value}"},
        "splitLine": {"show": True, "lineStyle": {"color": "#e5e5e5"}}
    },
    "yAxis": {
        "type": "value",
